func Open[P any](ctx context.Context, config Config[P]) (*App[P], error) {
	return golemOpen(ctx, config, golemruntime.Config[P, Actor]{Database: config.Database, Queue: config.Queue})
}

func golemOpen[P any](ctx context.Context, config Config[P], engineConfig golemruntime.Config[P, Actor]) (*App[P], error) {
	bindings, err := GolemGeneratedApplicationBindings()
	if err != nil {
		return nil, err
	}
	descriptors, err := GolemGeneratedApplicationDescriptors()
	if err != nil {
		return nil, err
	}
	eventRegistry := golem.EventRegistry{}
	eventFactories := golemruntime.EventFactoryRegistry{}
	engineConfig.Bundle = GolemGeneratedSchemaBundle()
	engineConfig.Bindings = bindings
	engineConfig.Descriptors = descriptors
	engineConfig.Embeddings = config.Embeddings
	engineConfig.ReadLimits = config.ReadLimits
	engineConfig.MutationLimits = config.MutationLimits
	engineConfig.AnalyticsLimits = config.AnalyticsLimits
	engineConfig.EventRegistry = eventRegistry
	engineConfig.EventFactories = eventFactories
	engineConfig.EventLimits = config.EventLimits
	engineConfig.EventTransport = config.EventTransport
	engineConfig.Observer = config.Observer
	engineConfig.CDCAdapters = config.CDCAdapters
	engineConfig.ReportEventOperator = config.ReportEventOperator
	engineConfig.HistoricalEventBundles = config.HistoricalEventBundles
	engineConfig.AfterCommitError = config.AfterCommitError
	engineConfig.AuditPrincipal = config.AuditPrincipal
	engineConfig.ReportScopedQuery = config.ReportScopedQuery
	engineConfig.ResolvePrincipal = config.ResolvePrincipal
	engineConfig.SnapshotPrincipal = config.SnapshotPrincipal
	engineConfig.SnapshotActor = config.SnapshotActor
	engine, err := golemruntime.Open(ctx, engineConfig)
	if err != nil {
		return nil, err
	}
	return &App[P]{runtime: engine, observer: config.Observer, provider: config.Database.Provider()}, nil
}

func (app *App[P]) RunEventPublisher(ctx context.Context) error {
	if app == nil {
		return events.Failure(events.CodeEventConfig)
	}
	return app.runtime.RunEventPublisher(ctx)
}
func (app *App[P]) RefreshSemanticIndexes(ctx context.Context) error {
	if app == nil {
		return fmt.Errorf("P9_SEMANTIC_RUNTIME: application is required")
	}
	return app.runtime.RefreshSemanticIndexes(ctx)
}
func (app *App[P]) RunQueueWorker(ctx context.Context) error {
	if app == nil {
		return queue.Fail(queue.CodeConfigInvalid, "application is required")
	}
	return app.runtime.RunQueueWorker(ctx)
}
func (app *App[P]) Enqueue(ctx context.Context, pending queue.Pending) (queue.JobID, error) {
	if app == nil {
		return "", queue.Fail(queue.CodeConfigInvalid, "application is required")
	}
	return app.runtime.Enqueue(ctx, pending)
}
